  out.push({ name: 'Marketing funnel opportunity counts match sf_opportunities', bad: (T.marketing_funnel || []).filter((f) => f.opps_created !== (T.sf_opportunities || []).filter((o) => M.fiscal(o.created_date).label === f.fiscal_quarter && o.lead_source === f.channel).length).length });
